class InterCourierChargeDialogController{constructor($scope,$mdDialog,$http,DispatchData,toastrService,staffId){this.$scope=$scope;this.$mdDialog=$mdDialog;this.$http=$http;this.DispatchData=DispatchData;this.toastrService=toastrService;this.isLoading=false;this.data={fromCourierId:0,toCourierId:0,reference:"",zones:0,amount:0,staffId:staffId};this.courierChargeForm=$scope.courierChargeForm;this.fromCourierSearchText="";this.toCourierSearchText="";this.fromCourierSelectedItem=null;this.toCourierSelectedItem=null}async courierSearch(searchTerm){try{const url="/courier/AllActiveSearch";return await this.DispatchData.autocompleteSearch(searchTerm,url)}catch(error){this.toastrService.showErrorToast(error.message)}}updateAmountByZones(zones){if(typeof zones!=="number"||isNaN(zones)){throw new Error("zones must be a valid number")}this.data.amount=(this.data.amount||0)+zones*7}async submit(data){try{this.isLoading=true;if(!this.courierChargeForm.$valid){this.toastrService.showWarningToast("Please complete all the required fields.");this.isLoading=false;return}data.fromCourierId=this.fromCourierSelectedItem.id;data.toCourierId=this.toCourierSelectedItem.id;const url="job/InterCourierCharge";await this.$http.post(url,data,{headers:{"Content-Type":"application/json"}});this.toastrService.showSuccessToast("Inter-Courier Charge saved successfully");this.$mdDialog.hide()}catch(error){this.toastrService.showErrorToast(error.message)}finally{this.isLoading=false}}cancel(){this.$mdDialog.cancel()}}